/// 向文件描述符写入数据。
///
/// see <https://man7.org/linux/man-pages/man2/write.2.html>.
#[inline]
pub fn write(fd: usize, buffer: &[u8]) -> isize {
    // SAFETY: buffer 是有效的切片引用，其指针和长度在调用期间有效
    unsafe { syscall3(SyscallId::WRITE, fd, buffer.as_ptr() as _, buffer.len()) }
}

/// 从文件描述符读取数据。
